/// One integration by SciPy: the problem, the tolerances, the accepted steps, the evaluations
/// of the right-hand side, the Jacobians, the LU decompositions and the state at `t1`.
pub struct Run<P: 'static> {
    pub problem: P,
    pub rtol: f64,
    pub atol: f64,
    pub steps: usize,
    pub nfev: usize,
    pub njev: usize,
    pub nlu: usize,
    pub y: &'static [f64],
}

